def Calculate_UL_throughoutput(alias, location=14, size=2000, cellid='', sleep_time=5):
    ssh.send_command('journalctl -f | grep --line-buffered rlcPdus | grep "{}"'.format(cellid),
                     connection=alias, timeout=60)
    time.sleep(sleep_time)
    output = ssh.read_output(size=size, connection=alias).split('\r\n')
    ul_output = output[0].split('\n')
    ul_output.pop()
    num = 0
    sum = 0
    for element in ul_output:
        data = element.split(' ')[location]
        traffic_data = data.split('(')[-1]
        num += 1
        sum += int(traffic_data)
        logger.info("Traffic data {} bytes received from UE".format(traffic_data))
    UL_Throughoutput = round(float(8 * Decimal(sum) / Decimal(num) / 1048576), 3)
    logger.info("UL_Throughoutput is {}".format(UL_Throughoutput))
    return UL_Throughoutput


def Calculate_DL_throughoutput_re(alias, sample=10, cellid='', sleep_time=10, start_offset=3, log_type='journallog',
                                  log_path='/tmp/data_dl.txt'):
    """
    calculate average dl throughput online with samples needed

    :param alias: the connection which can check this log print
    :param log_type: str: which type of log to be collected. Supported value: journallog/aasyslog.
    :param sample: with how many samples to caculate the average throughput
    :param cellid: str: when using multiple cell env, cell id is needed to filter which output is the target.
    :param sleep_time: int: how long this capture is going to wait.
                            For aasyslog it means the average interval with each log print.
    :param start_offset: with the log print caculate started from which line
    :param log_path: When using aasyslog, a log path is needed to store the log file to target directory.
    :return: average dl throughput
    """
    return caculate_l2_lo_throughput(
        direction='DL', alias=alias, log_type=log_type,
        sample=sample, cellid=cellid, sleep_time=sleep_time,
        start_offset=start_offset, log_path=log_path
    )


def Calculate_UL_throughoutput_re(alias, sample=10, cellid='', sleep_time=10, start_offset=3, log_type='journallog',
                                  log_path='/tmp/data_ul.txt'):
    """
    calculate average ul throughput online with samples needed

    :param alias: the connection which can check this log print
    :param log_type: str: which type of log to be collected. Supported value: journallog/aasyslog.
    :param sample: with how many samples to caculate the average throughput
    :param cellid: str: when using multiple cell env, cell id is needed to filter which output is the target.
    :param sleep_time: int: how long this capture is going to wait for journal log.
                            For aasyslog it means the average interval with each log print.
    :param start_offset: with the log print caculate started from which line
    :param log_path: When using aasyslog, a log path is needed to store the log file to target directory.
    :return: average ul throughput
    """
    return caculate_l2_lo_throughput(
        direction='UL', alias=alias, log_type=log_type,
        sample=sample, cellid=cellid, sleep_time=sleep_time,
        start_offset=start_offset, log_path=log_path
    )


def caculate_l2_lo_throughput(direction, alias,
                              log_type='journallog', sample=10, cellid='', sleep_time=10,
                              start_offset=3, log_path='/tmp/l2_throughput.txt'):
    """
    function to get l2 lo throughput via Journallog/ AaSyslog on gnb. Supporting both UL and DL.

    :param direction: str: direction of throughput. Supported value: ul/ dl
    :param alias: the connection which can check this log print
    :param log_type: str: which type of log to be collected. Supported value: journallog/aasyslog.
    :param sample: with how many samples to caculate the average throughput
    :param cellid: str: when using multiple cell env, cell id is needed to filter which output is the target.
    :param sleep_time: int: how long this capture is going to wait.
                            For aasyslog it means the average interval with each log print.
    :param start_offset: with the log print caculate started from which line
    :param log_path: When using aasyslog, a log path is needed to store the log file to target directory.
    :return: average throughput
    """
    connection = ssh.get_connection_by_alias(alias)

    if direction.lower() == 'ul':
        oneline_size = 300
        filter = 'rlcPdus'
        parser = _ul_data_pdu_parser
    elif direction.lower() == 'dl':
        oneline_size = 400
        filter = 'DataPdu'
        parser = _dl_data_pdu_parser
    else:
        raise ValueError("Wrong direction value: {}".format(direction))

    if log_type.lower() == 'journallog':
        output = _get_journal_output(
            ssh=connection, cellid=cellid, filter=filter, sample=sample,
            start_offset=start_offset, oneline_size=oneline_size, interval=sleep_time)
    elif log_type.lower() == 'aasyslog':
        output = _get_aasyslog_output(
            ssh=connection, cellid=cellid, filter=filter, log_path=log_path,
            sample=sample, start_offset=start_offset, interval=sleep_time)
    else:
        raise ValueError("Wrong log_type value: {}".format(log_type))
    logger.info("the data throughput print is {}".format(output))
    throughput = _caculate_tput(output, parser, sample, start_offset, 0)
    logger.info("{direction}_Throughoutput is {throughput}".format(direction=direction, throughput=throughput))
    return throughput


def _get_journal_output(ssh, cellid, filter, sample, start_offset, oneline_size, interval):
    ssh_process = ssh.send_command(
        r'journalctl -f|grep --line-buffered -i {} |grep "{}"'.format(filter, cellid), timeout=60)
    time.sleep(interval)
    data_pdu = ssh_process.read_output(size=(sample + start_offset) * oneline_size).split('\r\n')
    output = data_pdu[0].split('\n')
    output.pop()
    return output


def _get_aasyslog_output(ssh, cellid, filter, log_path, sample, start_offset, interval):
    i = 0
    time.sleep(sample * 1)
    while True:
        output = ssh.execute(
            command=r'cat {}| grep -a "{}"|grep -a "{}"'.format(log_path, filter, cellid), timeout=10).split('\r\n')
        if len(output) > (sample + start_offset) or i >= interval:
            break
        else:
            i += 1
            time.sleep(sample * 1)
            continue
    return output


def _caculate_tput(data_pdu_list, data_pdu_element_parser, sample, start_offset, location):
    sum = 0
    tp_accuracy = 3
    for element in data_pdu_list[start_offset:start_offset + sample]:
        traffic_data = data_pdu_element_parser(element, location)
        sum += int(traffic_data)
        logger.info("Traffic data {} bytes received from UE".format(traffic_data))
    tp_average = _caculate_average(sum, sample, tp_accuracy)
    return tp_average


def _caculate_average(summary, sample, accuracy):
    tp_average = round(_byte2megabit(summary) / sample, accuracy)
    return tp_average


def _dl_data_pdu_parser(element, location):
    data = re.findall(r"DataPdu:(.+?)]", element)
    return data[location].split('|')[-1].split(']')[0]


def _ul_data_pdu_parser(element, location):
    data = re.findall(r"\((.+?)rlcPduBytes", element)
    return data[location].split(' ')[0]


def calculate_average_of_the_throughput_listed_in_file(file_name):
    """
    calculate average throughput from file
    :param file_name: name of file contains throughput data
    :return: average throughput by megabit
    """
    data_sum = 0
    data_cnt = 0
    with open(file_name, 'r') as f:
        for line in f:
            line_data = line.rstrip()
            if re.match(r'\d+', line_data):
                data_sum += int(line_data)
                data_cnt += 1

    if data_cnt == 0:
        return data_cnt

    return _byte2megabit(data_sum / data_cnt)


def _byte2megabit(value):
    """
    covert byte number to megabit byte number
    :param int value: byte number
    :return: float megabit number
    """
    return value * 8 / 1000 / 1024.0


def calculate_e2e_throughput(alias, port, iperf_path='iperf', size=1000, sleep_time=5):
    """
    receive the throughput from end side like APPserver,Prisma control PC,qualcomm control pc
    and caculate the received avarage value
    :param alias:
    :param port: the same value with the data start.
    :param iperf_path:the iperf path ,if qualcomm use this need change to "adb shell iperf"
    :param size:the scope to caculate the average data throughput value
    :return: average_value
    """
    ssh.send_command(iperf_path + ' -s -u -i 1 -p ' + port + ' -P 1 -f m -l 1024B', connection=alias, timeout=60)
    time.sleep(sleep_time)
    output = ssh.read_output(size=size, connection=alias).split('\r\n')
    if len(output) == 1:
        output = output[0].split('\n')
    num = 0
    sum = 0
    for element in output:
        if 'Mbits/sec' in element:
            num += 1
            data = element.split('MBytes')
            traffic_data = data[1].split('Mbits/sec')
            traffic_value = traffic_data[0].strip()
            sum += float(traffic_value)
    average_value = round(Decimal(sum) / Decimal(num), 3)
    return average_value
